#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Copy the markdown text into a string stream
    std::stringstream markdownStream(markdown);

    // Convert the markdown text to HTML
    std::stringstream htmlStream;
    htmlStream << markdownStream;

    // Return the HTML text as a string
    return htmlStream.str();
}

int main() {
    std::string markdown = "# Markdown Text\n\nThis is a sample markdown text.";
    std::string html = markdownToHtml(markdown);
    std::cout << "Original: " << markdown << std::endl;
    std::cout << "Html: " << html << std::endl;
    return 0;
}
```

